  "guide.legacy.characterConstellations_helpers.b02442": {
    "text": "Unleashing her Elemental Skill Eternal Tides will immediately trigger an effect equivalent to the effect of Gravity Interference. This effect can be triggered once every 15s.\nMoonsign: Ascendant Gleam\nWhen Gravity Interference is triggered, if the Lunar reaction type that has accumulated the most Gravity for Columbina is:\n· Lunar-Charged: Your current active character will recover 6 Energy.\n· Lunar-Bloom: Your active character's interruption resistance will be increased for 8s.\n· Lunar-Crystallize: Summons a Rainsea Shield. The Rainsea Shield's DMG absorption is based on 12% of Columbina's Max HP, and it will absorb Hydro DMG with 250% effectiveness for 8s.\nAll nearby party members' Lunar Reaction DMG is elevated by 1.5%.",
    "sourceHash": null,
    "origin": "legacy",
    "review": "pending"
  },
  "guide.legacy.characterConstellations_helpers.b02443": {
    "text": "Not in Lone Splendor",
    "sourceHash": null,
    "origin": "legacy",
    "review": "pending"
  },
  "guide.legacy.characterConstellations_helpers.b02444": {
    "text": "Rate of accumulating Gravity increases by 34%. \nWhen Gravity Interference is triggered, Columbina will receive the Lunar Brilliance effect, which increases her Max HP by 40% for 8s.\nMoonsign: Ascendant Gleam:\nWhen Lunar Brilliance is active, if, during the current trigger of Gravity Interference, the Lunar reaction type that has accumulated the most Gravity for Columbina is:\n· Lunar-Charged: ATK of your current active character increases. Increase in ATK is equal to 1% of Columbina's Max HP.\n· Lunar-Bloom: Elemental Mastery of your current active character increases. Increase in Elemental Mastery is equal to 0.35% of Columbina's Max HP.\n· Lunar-Crystallize: DEF of your current active character increases. Increase in DEF is equal to 1% of Columbina's Max HP.\nAll nearby party members' Lunar Reaction DMG is elevated by 7%.",
    "sourceHash": null,
    "origin": "legacy",
    "review": "pending"
  },
